  c.windows=VoltageScaffoldWindowsTarget{id.slot,alternate?"PCI\\VEN_10DE&DEV_1234&SUBSYS_76543210\\ALT":"PCI\\VEN_10DE&DEV_99AA&SUBSYS_12345678\\CURRENT","SYSTEM\\CurrentControlSet\\Control\\Class\\{4d36e968-e325-11ce-bfc1-08002be10318}\\0007"};c.registry=PowerWeightRegistrySnapshot{{L"Unrelated",4,{0xde,0xad,0xbe,0xef}}};
