 fake=WeightFake();fake.current.info[0x41d0+31*0x24]=7;service.read();weight_check(service.state().rows[0].eligible_for_preview&&!service.state().rows[1].eligible_for_preview,"Unknown peer relationship does not suppress understood selected row");weight_check(service.preview({{0,1.25,4096}}).ok,"Qualified selection previews despite unrelated unknown peer");
 fake=WeightFake();fake.current.registry_availability=VoltagePolicyAvailability::transient;fake.current.registry_message="Registry read failed";fake.current.registry.reset();weight_check(!service.preview({{0,1.25,4096}}).ok&&service.state().rows[0].eligible_for_preview,"Registry failure blocks Preview without removing read-only row qualification");fake=WeightFake();fake.thrown_transients=1;weight_check(service.read().rows[0].eligible_for_preview,"One thrown transient capture receives bounded read-only recovery");fake.thrown_transients=2;weight_check(service.read().rows[0].stale,"Exhausted bounded capture retains last-good stale rows");fake.current.adapter.uuid[4]='X';weight_check(!service.preview({{0,1.5,{}}}).ok,"Changed selected UUID refuses Preview");
